const issueNames={english_region_untranslated:'英文区域未翻译',prominent_english_untranslated:'重要标题未翻译',page_translation_coverage_low:'页面翻译覆盖不足',rendered_regions_crowded:'局部内容拥挤',rendered_regions_missing:'局部内容缺失',rendered_structure_drift:'表格或版面结构漂移',rendered_page_too_sparse:'页面内容明显缺失',rendered_text_too_small:'译文字号过小',toc_layout_suspect:'目录排版疑似错行',rotation_metadata_mismatch:'页面旋转方向异常',text_direction_mismatch:'文字方向异常',unexpected_repetition:'异常重复文字',unexpected_control_characters:'异常控制字符',strategy_preserved_source_region:'策略保留了英文区域',structured_region_fallback:'结构化区域回退',scan_render_mode_missing:'扫描页验收信息缺失'};
