function captureReviewDraft(){const key=reviewDraftKey();if(!key)return;reviewDrafts.set(key,{checked:[...$('#reviewDetail').querySelectorAll('[data-issue-check]:checked')].flatMap(item=>issueIdsFromDataset(item.dataset.issueCheck)),feedback:$('#reviewFeedback')?.value||''})}
