async function pollReview(){if(!reviewTask||reviewInteractionActive())return;await loadReview()}
function issueImpact(issue){if(['hard_blocker','needs_review','tip'].includes(issue.user_impact))return issue.user_impact;if(['red','critical'].includes(issue.severity))return'hard_blocker';if(issue.severity==='orange')return'needs_review';return'tip'}
function isActionableIssue(issue){return ['hard_blocker','needs_review'].includes(issueImpact(issue))}
function needsAction(issue){return isActionableIssue(issue)&&(issue.review?.decision||'pending')!=='ignored'}
function technicalIssues(target){return (target?.issues||[]).filter(issue=>!isActionableIssue(issue))}
function pageHumanReviews(target=reviewPage){return (reviewData?.human_reviews||[]).filter(item=>item.pdf_page===target?.pdf_page)}
function reviewVisiblePages(){const pages=reviewData?.pages||[];return pages.filter(target=>target.issues.some(needsAction)||pageHumanReviews(target).length||pageComments(target).length||(reviewShowTips&&technicalIssues(target).length))}
function reviewPickerPages(){const visible=reviewVisiblePages();if(reviewPage&&!visible.some(target=>target.pdf_page===reviewPage.pdf_page))visible.push(reviewPage);return visible.sort((a,b)=>a.pdf_page-b.pdf_page)}
async function showQa(id){const task=current===id&&currentTask?currentTask:await api('/api/tasks/'+id);if(!task.qa_alpha_file){alert('这份论文还没有确定性 QA 报告，暂时无法进入质量检查。');return}reviewTask=id;reviewPage=null;reviewShowTips=false;await loadReview();await openTask(id,reviewPage?.pdf_page||(current===id?page:1),{keepReview:true});setReviewOpen(true,{activate:true});updateWorkspaceControls()}
async function loadReview(){if(!reviewTask)return;captureReviewDraft();const previousPage=reviewPage?.pdf_page;[reviewData,reviewCycleData]=await Promise.all([api(`/api/tasks/${reviewTask}/qa-review`),api(`/api/tasks/${reviewTask}/review-cycle`)]);const all=reviewData.pages||[];const readerPage=reviewTask===current?page:null;reviewPage=all.find(target=>target.pdf_page===readerPage)||all.find(target=>target.pdf_page===previousPage)||reviewVisiblePages()[0]||all[0]||null;renderReviewPagePicker();renderDocumentReviewSummary();if(reviewPage){renderReviewDetail();renderRepairHistory()}else{renderRepairHistory();setTextIfChanged($('#reviewTitle'),'质量复核');setTextIfChanged($('#reviewSummary'),'没有可复核的页面。');$('#reviewDetail').classList.add('review-empty');setTextIfChanged($('#reviewDetail'),'当前 QA 报告没有页面数据。')}}
function renderReviewPagePicker(){const select=$('#reviewPageSelect');const pages=reviewPickerPages();const tips=Number(reviewData?.attention?.technical_tip_page_count||0);const stale=reviewData?.qa?.freshness?.status==='stale';setTextIfChanged($('#reviewPageLabel'),'当前页 / 待办');if(select.disabled===Boolean(pages.length))select.disabled=!pages.length;const options=pages.map(target=>{const actionable=target.issues.filter(needsAction).length;const human=pageHumanReviews(target).length;const comments=pageComments(target).length;const technical=technicalIssues(target).length;let label=actionable?`${actionable} 项${stale?'待确认':'需要处理'}${comments?` · ${comments} 条 Comment`:''}`:comments?`${comments} 条 Comment`:human?`${human} 条人工反馈`:reviewShowTips&&technical?`技术提示 ${technical} 条`:'当前页 · 无机器待办';return `<option value="${target.pdf_page}" ${reviewPage?.pdf_page===target.pdf_page?'selected':''}>第 ${target.pdf_page} 页 · ${label}</option>`}).join('');setHtmlIfChanged(select,options,'review-page-picker');select.onchange=()=>selectReviewPage(Number(select.value),true);const toggle=$('#reviewTipsToggle');if(toggle.hidden===Boolean(tips))toggle.hidden=!tips;toggle.classList.toggle('active',reviewShowTips);setAttrIfChanged(toggle,'aria-pressed',reviewShowTips);setTextIfChanged(toggle,reviewShowTips?'收起技术诊断':'技术诊断（按需）');toggle.onclick=()=>{captureReviewDraft();reviewShowTips=!reviewShowTips;renderReviewPagePicker();renderReviewDetail();renderRepairHistory()}}
function selectReviewPage(pdfPage,updatePdf=false){const found=reviewData?.pages.find(p=>p.pdf_page===pdfPage);if(!found)return;captureReviewDraft();reviewPage=found;if($('#reviewPageSelect').value!==String(pdfPage))$('#reviewPageSelect').value=String(pdfPage);renderReviewDetail();renderRepairHistory();if(updatePdf){page=pdfPage;renderPage()}}
function renderIssueCard(issue,{technical=false}={}){const decision=issue.review?.decision||'pending';const impact=issueImpact(issue);const tier=impact==='hard_blocker'?'需要处理':impact==='needs_review'?'需要复核':'技术提示';const copy=issuePresentation(issue);const decisionValue=decision==='ignored'?'pending':'ignored';const decisionText=decision==='ignored'?'恢复待复核':'忽略此项';return `<article class="issue impact-${escapeHtml(impact)} ${decision}${technical?' technical':''}"><div class="issue-topline"><label class="issue-select"><input type="checkbox" data-issue-check="${escapeHtml(issue.issue_id)}" ${decision==='ignored'||technical?'disabled':''}><span class="issue-badge">${escapeHtml(tier)}</span></label><small>${escapeHtml(decisionLabel(decision))}</small></div><h4>${escapeHtml(copy.title)}</h4><p class="issue-summary">${escapeHtml(copy.summary)}</p><details class="issue-why" data-detail-key="issue-why-${escapeHtml(issue.issue_id)}"><summary>为什么标记？</summary><p>${escapeHtml(copy.why)}</p></details><div class="issue-actions"><button class="micro ghost" data-decision="${decisionValue}" data-issue="${escapeHtml(issue.issue_id)}">${decisionText}</button>${technical?'':`<button class="micro issue-comment" data-comment-seed="${escapeHtml(issueCommentSeed(issue))}" data-comment-issue="${escapeHtml(issue.issue_id)}">加入 Comment</button>`}</div></article>`}
function issueGroups(issues){const groups=[];const byKey=new Map();issues.forEach(issue=>{const key=issue.issue_type||'unknown';if(!byKey.has(key)){const group={key,issues:[]};byKey.set(key,group);groups.push(group)}byKey.get(key).issues.push(issue)});return groups}
function renderIssueGroup(group,{technical=false}={}){if(group.issues.length===1)return renderIssueCard(group.issues[0],{technical});const sample=group.issues[0],impact=issueImpact(sample),copy=issuePresentation(sample),ids=group.issues.map(issue=>issue.issue_id).join(','),ignored=group.issues.every(issue=>(issue.review?.decision||'pending')==='ignored'),disabled=technical||ignored,decisionValue=ignored?'pending':'ignored',decisionText=ignored?'恢复此类待复核':`忽略此类 ${group.issues.length} 处`;const details=group.issues.map((issue,index)=>{const item=issuePresentation(issue);return `<li><b>${index+1}.</b> ${escapeHtml(item.summary)}${issue.evidence?`<small>${escapeHtml(issue.evidence)}</small>`:''}</li>`}).join('');return `<article class="issue aggregate impact-${escapeHtml(impact)} ${ignored?'ignored':'pending'}${technical?' technical':''}"><div class="issue-topline"><label class="issue-select"><input type="checkbox" data-issue-check="${escapeHtml(ids)}" ${disabled?'disabled':''}><span class="issue-badge">${escapeHtml(technical?'技术提示':impact==='hard_blocker'?'需要处理':'需要复核')}</span></label><small>${group.issues.length} 处 · ${escapeHtml(issueName(group.key))}</small></div><h4>${escapeHtml(copy.title)}（${group.issues.length} 处）</h4><p class="issue-summary">${escapeHtml(copy.summary)}</p><details class="issue-why" data-detail-key="issue-group-${escapeHtml(group.key)}"><summary>展开 ${group.issues.length} 处明细</summary><ul class="issue-detail-list">${details}</ul></details><div class="issue-actions"><button class="micro ghost" data-group-decision="${decisionValue}" data-group-issues="${escapeHtml(ids)}">${escapeHtml(decisionText)}</button>${technical?'':`<button class="micro issue-comment" data-comment-seed="${escapeHtml(`请关注：${copy.title}（${group.issues.length} 处）。${copy.summary}`)}" data-comment-issues="${escapeHtml(ids)}">加入 Comment</button>`}</div></article>`}
function renderIssueList(issues,{technical=false}={}){return issueGroups(issues).map(group=>renderIssueGroup(group,{technical})).join('')}
function structuralOcrBanner(target,issues){if(target?.route!=='ocr')return'';const group=issueGroups(issues).find(item=>item.issues.length>=3);if(!group)return'';return `<div class="structural-banner" role="status"><b>本页 OCR 质量差，属结构性问题</b><span>${escapeHtml(issueName(group.key))} 已折叠 ${group.issues.length} 处；请按整页阅读质量判断。</span></div>`}
function humanReviewCard(record){const diagnosis=record.diagnosis;const status=record.status==='advising'?'Claude 分析中':record.status==='diagnosed'?'已形成下一轮重点':record.status==='failed'?'分析失败':record.status;const result=diagnosis?`<div class="human-review-result"><b>${diagnosis.is_real_problem?'Claude 认为需要关注':'Claude 认为可能无需修复'}</b><p>${escapeHtml(diagnosis.explanation||'')}</p><small>建议：${escapeHtml(diagnosis.recommended_action||'')} · 风险 ${escapeHtml(diagnosis.risk||'')}</small></div>`:record.status==='failed'?`<p class="error">${escapeHtml(record.error||'Claude 分析失败')}</p>`:'<p class="working">正在只读分析本页，不会自动生成候选。</p>';return `<article class="human-review-card"><header><span>June 人工发现</span><small>${escapeHtml(status)}</small></header><p>${escapeHtml(record.feedback||'')}</p>${result}</article>`}
function pageComments(target=reviewPage){return (reviewCycleData?.comments||[]).filter(item=>item.pdf_page===target?.pdf_page)}
function commentDecisionLabel(value){return ({agree_needs_change:'同意需修改',agree_no_change:'同意无需修改',not_adopted:'不采纳',deferred:'暂缓',needs_more_info:'需要补充信息'})[value]||'待裁定'}
function agentReviewFor(id){return (reviewCycleData?.agent_reviews||[]).filter(item=>item.comment_id===id)}
function commentDecisionButtons(record){const options=[['agree_needs_change','同意需修改'],['agree_no_change','无需修改'],['not_adopted','不采纳'],['deferred','暂缓'],['needs_more_info','补充信息']];return `<div class="comment-decisions">${options.map(([value,label])=>`<button class="micro ghost" data-comment-decision="${value}" data-comment-id="${escapeHtml(record.comment_id)}" data-version="${record.object_version||1}">${label}</button>`).join('')}</div>`}
function commentDecisionPanel(record,reviews){if(!reviews.length)return'<p class="comment-safety">送审形成 AgentReview 后，再决定是否进入修复。</p>';if(!record.latest_decision)return commentDecisionButtons(record);const approved=record.latest_decision==='agree_needs_change';const title=approved?'已同意修改，已加入修复池':`已记录：${commentDecisionLabel(record.latest_decision)}`;const detail=approved?'当前 PDF 尚未改变。请点击上方“建立修复批次”生成隔离候选。':'这条意见不会进入当前修复池；如需调整，可在下方更改决定。';return `<div class="comment-decision-state ${approved?'approved':''}" role="status"><b>✓ ${escapeHtml(title)}</b><p>${escapeHtml(detail)}</p></div><details class="comment-redecide"><summary>更改决定</summary>${commentDecisionButtons(record)}</details>`}
function commentCard(record){const reviews=agentReviewFor(record.comment_id);const latest=reviews[0]?.result?.page_review||null;const status=record.status==='saved'?'待提交':record.status==='queued'?'排队中':record.status==='reviewed'?'已审阅':record.status==='review_failed'?'审阅失败':record.status==='approved_for_repair'?'已批准修复':record.status==='repair_applied'?'已完成修改':record.status==='needs_recheck'?'页面变化 · 待重核':record.status;const decision=commentDecisionLabel(record.latest_decision);const result=latest?`<div class="human-review-result"><b>AgentReview</b><p>${escapeHtml(latest.explanation||latest.recommended_action||JSON.stringify(latest).slice(0,260))}</p></div>`:record.last_error?`<p class="error">${escapeHtml(record.last_error)}</p>`:'';return `<article class="comment-card" data-comment="${escapeHtml(record.comment_id)}"><header><label><input type="checkbox" data-comment-check="${escapeHtml(record.comment_id)}" ${['queued','reviewed','approved_for_repair','repair_applied'].includes(record.status)?'disabled':''}><span>Comment</span></label><small>${escapeHtml(status)} · ${escapeHtml(decision)} · v${record.object_version||1}</small></header><p>${escapeHtml(record.feedback||'')}</p>${result}${commentDecisionPanel(record,reviews)}</article>`}
function reviewQueueSummary(){const jobs=reviewCycleData?.agent_review_jobs||[];const active=jobs.filter(j=>j.status==='active').length,queued=jobs.filter(j=>j.status==='queued').length,failed=jobs.filter(j=>j.status==='failed').length;if(!jobs.length&&!active&&!queued&&!failed)return'';const latest=jobs[0];const detail=latest?`最近批次：${latest.page_group_count||0} 页组 · ${latest.comment_count||0} 条 · ${latest.status}`:'';return `<div class="review-queue"><span>AgentReview 队列</span><small>进行中 ${active} · 排队 ${queued} · 失败 ${failed}</small>${detail?`<p>${escapeHtml(detail)}</p>`:''}</div>`}
function commentSection(){const comments=pageComments();if(!comments.length)return'';const pending=comments.filter(c=>['saved','review_failed'].includes(c.status));return `<section class="comment-section"><h3>已有 Comment · ${comments.length}</h3>${reviewQueueSummary()}<div class="comment-list">${comments.map(commentCard).join('')}</div><div class="comment-bulk"><button id="submitCheckedComments" ${pending.length?'':'disabled'}>提交勾选 Comment</button><button class="ghost" id="submitPendingComments" ${pending.length?'':'disabled'}>提交本页待审 ${pending.length} 条</button></div></section>`}
function cycleCounts(){return{pending:Number(reviewCycleData?.pending_comment_count||0),reviewing:Number(reviewCycleData?.queued_review_count||0)+Number(reviewCycleData?.active_review_count||0),awaiting:Number(reviewCycleData?.awaiting_decision_count||0),approved:Number(reviewCycleData?.approved_repair_item_count||0)}}
function approvedRepairPageCount(){return new Set((reviewCycleData?.approved_repair_items||[]).filter(item=>item.eligible).map(item=>Number(item.pdf_page||0))).size}
function formalVersionSummary(){const formal=reviewCycleData?.formal_output||{};const source=formal.source_kind==='repair_batch'&&formal.source_batch_id?`RepairBatch ${formal.source_batch_id}`:'初译正式稿';const installed=formal.installed_at?new Date(formal.installed_at*1000).toLocaleString():'安装时间未知';const batch=reviewCycleData?.open_repair_batch_id?`开放批次：${reviewCycleData.open_repair_batch_id} · ${reviewCycleData.open_repair_batch_status||'unknown'}`:'无开放批次';const candidate=reviewCycleData?.has_uninstalled_candidate?`未安装候选：${reviewCycleData.ready_candidate_id||'存在'} · ${reviewCycleData.ready_candidate_status||'candidate_ready'}`:'无未安装候选';const warning=formal.contract_warning?` · 合同警示：${formal.contract_warning.message||formal.contract_warning.status}`:'';return `正式稿：${source} · ${installed} · ${batch} · ${candidate}${warning}`}
function openBatch(){const id=reviewCycleData?.open_repair_batch_id;return(reviewCycleData?.repair_batches||[]).find(item=>item.batch_id===id)||null}
function cyclePrimaryAction(){const counts=cycleCounts(),batch=openBatch();if(batch){if(batch.status==='candidate_ready')return{action:'batch',label:'预览并决定最终候选'};if(batch.status==='repairing')return{action:'batch',label:batch.progress?.message||'修复候选生成中…',disabled:true};if(batch.status==='awaiting_page_decisions')return{action:'batch',label:batch.one_click?.result_state==='blocked'?'查看已拦截页面原因':'逐页决定修复结果'};if(batch.status==='preflight_ready')return{action:'batch',label:'确认生成隔离修复候选'};return{action:'batch',label:'查看修复批次'}}if(counts.approved)return{action:'repair',label:`生成可验收修复版（${approvedRepairPageCount()} 页）`};if(counts.pending)return{action:'comments',label:`批量提交本篇待审 Comment（${counts.pending}）`};if(counts.awaiting)return{action:'decisions',label:`裁定审阅意见（${counts.awaiting}）`};if(counts.reviewing)return{action:'none',label:'Agent 正在审阅已提交 Comment',disabled:true};return{action:'none',label:'本篇暂无待提交或待修复项目',disabled:true}}
function renderDocumentReviewSummary(){const target=$('#documentReviewSummary');if(!target)return;const counts=cycleCounts(),action=cyclePrimaryAction();const chips=[['待送审',counts.pending],['审阅中',counts.reviewing],['待裁定',counts.awaiting],['已批准',counts.approved]].map(([label,value])=>`<span class="cycle-count ${value?'active':''}">${label} <strong>${value}</strong></span>`).join('');const batch=openBatch();const progress=batch?.progress?.message?`<div class="cycle-progress">${escapeHtml(batch.progress.message)}</div>`:'';const html=`<div class="cycle-strip"><div class="cycle-strip-head"><b>本篇审校进度</b><small>${batch?`RepairBatch · ${escapeHtml(batch.status)}`:'跨页汇总'}</small></div><div class="cycle-counts">${chips}</div><button class="cycle-primary" id="cyclePrimary" data-cycle-action="${action.action}" ${action.disabled?'disabled':''}>${escapeHtml(action.label)}</button>${progress}<div class="formal-status ${reviewCycleData?.formal_output?.contract_warning?'warning':''}" role="status">${escapeHtml(formalVersionSummary())}</div><div class="cycle-secondary"><span>当前页可继续记录，不要求一次审完全文。</span>${counts.pending?`<button class="micro ghost" id="cycleViewPending">查看 ${counts.pending} 条</button>`:''}</div></div>`;setHtmlIfChanged(target,html,'document-review-summary');const primary=$('#cyclePrimary');if(primary&&!primary.disabled)primary.onclick=()=>openCycleAction(primary.dataset.cycleAction);const pending=$('#cycleViewPending');if(pending)pending.onclick=()=>openBulkCommentDialog()}
function cycleDialogShell(title,summary,body,actions){$('#cycleDialogTitle').textContent=title;$('#cycleDialogSummary').textContent=summary;$('#cycleDialogBody').innerHTML=body;$('#cycleDialogActions').innerHTML=actions;$('#cycleDialogError').hidden=true;const dialog=$('#cycleDialog');if(!dialog.open)dialog.showModal()}
function closeCycleDialog(){$('#cycleDialog').close()}
function groupByPage(items){return items.reduce((groups,item)=>{const key=Number(item.pdf_page||0);(groups[key]||(groups[key]=[])).push(item);return groups},{})}
function openCycleAction(action){if(action==='comments')return openBulkCommentDialog();if(action==='decisions')return openAwaitingDecisionDialog();return openRepairBatchDialog()}
function openBulkCommentDialog(){const pending=(reviewCycleData?.comments||[]).filter(item=>['saved','review_failed'].includes(item.status));const groups=groupByPage(pending);const body=Object.entries(groups).sort((a,b)=>Number(a[0])-Number(b[0])).map(([pdfPage,items])=>`<section class="cycle-group"><h3>第 ${pdfPage} 页 · ${items.length} 条</h3>${items.map(item=>`<label class="cycle-item"><input type="checkbox" data-cycle-comment="${escapeHtml(item.comment_id)}" checked><span class="cycle-item-copy"><header><b>Comment</b><small>${escapeHtml(item.status==='review_failed'?'上次失败，可重试':'待送审')}</small></header><p>${escapeHtml(item.feedback||'')}</p></span></label>`).join('')}</section>`).join('')||'<p class="cycle-note success">本篇没有待送审 Comment。</p>';cycleDialogShell('批量提交本篇 Comment',`共 ${pending.length} 条，按页面归并送审；提交不会修改 PDF。`,body,`<button class="ghost" type="button" id="cycleCancel">取消</button><button type="button" id="cycleSubmitComments" ${pending.length?'':'disabled'}>提交选中 Comment 审阅</button>`);$('#cycleCancel').onclick=closeCycleDialog;const submit=$('#cycleSubmitComments');if(submit)submit.onclick=submitDocumentComments}
async function submitDocumentComments(){const ids=[...$('#cycleDialogBody').querySelectorAll('[data-cycle-comment]:checked')].map(item=>item.dataset.cycleComment);if(!ids.length){showCycleError('请至少选择一条 Comment。');return}const button=$('#cycleSubmitComments');button.disabled=true;button.textContent='正在加入审阅队列…';try{const result=await api(`/api/tasks/${reviewTask}/agent-reviews`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comment_ids:ids,provider:$('#provider')?.value||'claude'})});closeCycleDialog();await loadReview();if(result.rejected?.length)alert(`${result.accepted.length} 条已入队，${result.rejected.length} 条因状态变化未重复提交。`)}catch(error){showCycleError(error.message);button.disabled=false;button.textContent='提交选中 Comment 审阅'}}
function cycleCommentDecisionActions(item){return `<div class="comment-decision-inline"><button class="micro" type="button" data-cycle-comment-decision="agree_needs_change" data-comment-id="${escapeHtml(item.comment_id)}" data-version="${item.object_version||1}">进修复</button><button class="micro ghost" type="button" data-cycle-comment-decision="not_adopted" data-comment-id="${escapeHtml(item.comment_id)}" data-version="${item.object_version||1}">作废移除</button></div>`}
function bindCommentDecisionButtons(root,reopen){root.querySelectorAll('[data-cycle-comment-decision]').forEach(button=>button.onclick=async event=>{event.preventDefault();event.stopPropagation();try{await decideComment(button.dataset.commentId,button.dataset.cycleCommentDecision,Number(button.dataset.version||0));await loadReview();if(reopen==='decisions')openAwaitingDecisionDialog();if(reopen==='repair')openRepairBatchDialog()}catch(error){showCycleError(error.message);await loadReview()}})}
function openAwaitingDecisionDialog(){const comments=(reviewCycleData?.comments||[]).filter(item=>item.status==='reviewed'&&!item.latest_decision);const approved=(reviewCycleData?.comments||[]).filter(item=>item.latest_decision==='agree_needs_change');const rows=[...comments,...approved];const groups=groupByPage(rows);const body=Object.entries(groups).sort((a,b)=>Number(a[0])-Number(b[0])).map(([pdfPage,items])=>`<section class="cycle-group"><h3>第 ${pdfPage} 页</h3>${items.map(item=>{const isApproved=item.latest_decision==='agree_needs_change';return `<article class="cycle-item"><span></span><span class="cycle-item-copy"><header><b>${isApproved?'已批准进入修复':'等待你的决定'}</b><small>${isApproved?'可撤回批准':'AgentReview 已完成'}</small></header><p>${escapeHtml(item.feedback||'')}</p>${isApproved?`<div class="comment-decision-inline"><button class="micro ghost" type="button" data-cycle-comment-decision="not_adopted" data-comment-id="${escapeHtml(item.comment_id)}" data-version="${item.object_version||1}">撤回批准</button></div>`:cycleCommentDecisionActions(item)}</span></article>`}).join('')}</section>`).join('')||'<p class="cycle-note success">没有待裁定意见。</p>';cycleDialogShell('裁定审阅意见',`待裁定 ${comments.length} 条，已批准 ${approved.length} 条；Agent 的建议不会自动批准修改。`,body,'<button type="button" id="cycleDone">完成</button>');$('#cycleDone').onclick=closeCycleDialog;bindCommentDecisionButtons($('#cycleDialogBody'),'decisions')}
function repairPoolBody(pool){const groups=groupByPage(pool);return Object.entries(groups).sort((a,b)=>Number(a[0])-Number(b[0])).map(([pdfPage,items])=>`<section class="cycle-group"><h3>第 ${pdfPage} 页 · ${items.length} 项</h3>${items.map(item=>`<label class="cycle-item ${item.eligible?'':'blocked'}"><input type="checkbox" data-repair-item="${escapeHtml(item.key)}" ${item.eligible?'checked':'disabled'}><span class="cycle-item-copy"><header><b>${item.source_type==='comment'?'人工 Comment':'机器红色问题'}</b><small>${escapeHtml(item.family||'不可执行')}</small></header><p>${escapeHtml(item.summary||'')}</p>${item.blocked_reasons?.length?`<p class="error">${escapeHtml(item.blocked_reasons.join('；'))}</p>`:''}${item.source_type==='comment'?`<button class="micro ghost" type="button" data-cycle-comment-decision="not_adopted" data-comment-id="${escapeHtml(item.source_id)}" data-version="${item.source_version||1}">撤回批准</button>`:''}</span></label>`).join('')}</section>`).join('')}
function previewImageUrl(batchId,name){return `/api/tasks/${reviewTask}/repair-batches/${batchId}/preview/${encodeURIComponent(name)}`}
function modelObservationBlock(item){const obs=item.model_observation||{status:'pending'},result=obs.result||{};if(obs.status==='ready'){const rows=[['阅读顺序',result.reading_order_ok?'未见破坏':'需要人工留意',result.reading_order_note],['保护内容',result.protected_content_ok?'未见缺失':'需要人工留意',result.protected_content_note],['问题改善',result.comment_issue_improved?'观察到改善':'未确认改善',result.comment_issue_note]].map(([label,state,note])=>`<li><b>${escapeHtml(label)}：</b>${escapeHtml(state)}${note?` · ${escapeHtml(note)}`:''}</li>`).join('');const extra=(result.observations||[]).slice(0,4).map(note=>`<li>${escapeHtml(note)}</li>`).join('');return `<aside class="model-observation ready"><h4>模型观察</h4><ul>${rows}${extra}</ul></aside>`}if(obs.status==='unavailable')return `<aside class="model-observation unavailable"><h4>模型观察</h4><p>${escapeHtml(obs.message||'标注不可用')}</p></aside>`;return `<aside class="model-observation pending"><h4>模型观察</h4><p>${obs.status==='running'?'标注生成中':'等待标注'}</p></aside>`}
function previewPageCard(batch,item){const metrics=Object.keys(item.gate?.metrics||{}).length?JSON.stringify(item.gate.metrics):'无额外指标';const fallbacks=(item.fallbacks||[]).length?item.fallbacks.map(value=>`<li>${escapeHtml(value)}</li>`).join(''):'<li>无 fallbacks</li>';const violations=(item.new_violations||[]).length?item.new_violations.map(value=>`<li>${escapeHtml(value.issue_type||value.type||JSON.stringify(value))}</li>`).join(''):'<li>无新增违规</li>';return `<article class="candidate-preview-page"><header><b>第 ${item.pdf_page} 页</b><small>${escapeHtml(item.gate?.machine_gate||'gate')}</small></header><div class="preview-page-grid"><div><div class="preview-images"><figure><img src="${previewImageUrl(batch.batch_id,item.before_image)}" alt="第 ${item.pdf_page} 页修复前裁剪"><figcaption>修复前</figcaption></figure><figure><img src="${previewImageUrl(batch.batch_id,item.after_image)}" alt="第 ${item.pdf_page} 页修复后裁剪"><figcaption>修复后</figcaption></figure></div><div class="preview-facts"><dl><dt>门指标</dt><dd>${escapeHtml(item.gate?.qa_status||'unknown')} · ${escapeHtml(metrics)}</dd><dt>机器门原因</dt><dd>${escapeHtml((item.gate?.reasons||[]).join('；')||'通过')}</dd><dt>Fallbacks</dt><dd><ul>${fallbacks}</ul></dd><dt>新增违规</dt><dd><ul>${violations}</ul></dd></dl></div></div>${modelObservationBlock(item)}</div><div class="patch-decisions"><button type="button" class="ghost" data-patch-decision="exclude" data-patch-id="${escapeHtml(item.page_patch_id)}" data-version="${((reviewCycleData?.page_patches?.[batch.batch_id]||[]).find(p=>p.page_patch_id===item.page_patch_id)||{}).object_version||1}">剔除此页并重组</button></div></article>`}
function candidatePreviewBody(batch){const candidate=batch.candidate||{},preview=candidate.preview||{},pages=preview.changed_pages||[];const summary=`<p class="cycle-note success">全篇 QA 已完成，没有新增 red hard blocker。变更页 ${escapeHtml((candidate.included_pages||[]).join('、')||'无')}。</p><p class="cycle-note"><a target="_blank" href="/api/tasks/${reviewTask}/repair-batches/${batch.batch_id}/file/dual">打开候选双语 PDF</a></p>`;return `${summary}${pages.length?pages.map(item=>previewPageCard(batch,item)).join(''):'<p class="cycle-note warning">没有生成变更页预览图，请使用候选 PDF 人工核对。</p>'}`}
function candidateObservationPending(batch){return (((batch.candidate||{}).preview||{}).changed_pages||[]).some(item=>!['ready','unavailable'].includes(item.model_observation?.status))}
async function startCandidateObservations(batch){if(candidateObservationStarted.has(batch.batch_id))return;candidateObservationStarted.add(batch.batch_id);try{await api(`/api/tasks/${reviewTask}/repair-batches/${batch.batch_id}/observations`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:$('#provider')?.value||currentTask?.provider||'claude'})})}catch(error){}scheduleCandidateObservationPoll(batch.batch_id)}
function scheduleCandidateObservationPoll(batchId){clearTimeout(candidateObservationPoll);candidateObservationPoll=setTimeout(()=>refreshCandidateObservationDialog(batchId).catch(()=>{}),3000)}
async function refreshCandidateObservationDialog(batchId){if(!$('#cycleDialog')?.open)return;reviewCycleData=await api(`/api/tasks/${reviewTask}/review-cycle`);const batch=(reviewCycleData?.repair_batches||[]).find(item=>item.batch_id===batchId);if(!batch||batch.status!=='candidate_ready')return;openRepairBatchDialog();if(candidateObservationPending(batch))scheduleCandidateObservationPoll(batchId)}
function patchBody(batch){const patches=reviewCycleData?.page_patches?.[batch.batch_id]||[];return patches.map(item=>`<article class="cycle-item ${item.machine_gate==='pass'?'':'failed'}"><span></span><span class="cycle-item-copy"><header><b>第 ${item.pdf_page} 页 · ${escapeHtml(item.family||'')}</b><small>${item.machine_gate==='pass'?'机器门通过':'不可纳入'}</small></header><p>${item.machine_gate_reasons?.length?escapeHtml(item.machine_gate_reasons.join('；')):'候选页已隔离生成；请查看后决定是否纳入。'}</p><div class="patch-decisions">${['include','exclude','defer'].map(decision=>`<button type="button" class="${item.decision===decision?'active':''}" data-patch-decision="${decision}" data-patch-id="${item.page_patch_id}" data-version="${item.object_version||1}" ${decision==='include'&&item.machine_gate!=='pass'?'disabled':''}>${decision==='include'?'纳入':decision==='exclude'?'剔除':'稍后'}</button>`).join('')}</div></span></article>`).join('')||'<p class="cycle-note warning">没有可供逐页决定的 PagePatch。</p>'}
function openRepairBatchDialog(){const batch=openBatch(),pool=reviewCycleData?.approved_repair_items||[];if(!batch){const eligible=pool.filter(item=>item.eligible);const pages=new Set(eligible.map(item=>Number(item.pdf_page||0))).size;cycleDialogShell('生成可验收修复版',`可执行 ${eligible.length} 项，覆盖 ${pages} 页；一键流会自动建批、预检、执行、纳入通过页、组装并检查。`,repairPoolBody(pool)||'<p class="cycle-note warning">当前没有已批准且可执行的修复项。</p>',`<button class="ghost" type="button" id="cycleCreateBatch" ${eligible.length?'':'disabled'}>分步建立批次</button><button type="button" id="cycleOneClickBatch" ${eligible.length?'':'disabled'}>生成可验收修复版（${pages} 页）</button>`);const create=$('#cycleCreateBatch');if(create)create.onclick=createBatch;const one=$('#cycleOneClickBatch');if(one)one.onclick=oneClickBatch;bindCommentDecisionButtons($('#cycleDialogBody'),'repair');return}const preflight=batch.preflight||{};if(batch.status==='preflight_ready'||batch.status==='preflight_blocked'){const body=`<p class="cycle-note ${batch.status==='preflight_ready'?'success':'warning'}">${batch.status==='preflight_ready'?`预检通过：${preflight.ready_page_count||0} 页，预计 ${preflight.estimated_ai_requests||0} 次页面请求。`:`预检被阻止：${(preflight.conflicts||[]).map(item=>(item.reasons||[]).join('；')).join('；')}`}</p>${(preflight.page_plans||[]).map(item=>`<article class="cycle-item ${item.status==='ready'?'':'blocked'}"><span></span><span class="cycle-item-copy"><header><b>第 ${item.pdf_page} 页</b><small>${escapeHtml(item.family||'冲突')}</small></header><p>${item.status==='ready'?`${item.source_count} 项意见已合并为一个页面计划。`:escapeHtml((item.blocked_reasons||[]).join('；'))}</p></span></article>`).join('')}`;cycleDialogShell('RepairBatch 预检',`批次 ${batch.batch_id}`,body,`<button class="ghost" type="button" id="cycleRejectBatch">关闭批次</button><button type="button" id="cycleStartBatch" ${batch.status==='preflight_ready'?'':'disabled'}>生成隔离修复候选</button>`);$('#cycleRejectBatch').onclick=()=>rejectBatch(batch.batch_id);$('#cycleStartBatch').onclick=()=>startBatch(batch.batch_id);return}if(batch.status==='repairing'){cycleDialogShell('正在生成修复候选','当前 PDF 保持不变；完成后自动纳入通过页并组装候选。',`<p class="cycle-note warning">${escapeHtml(batch.progress?.message||'修复器正在按页执行并运行机器检查。你可以关闭此窗口继续阅读，进度会自动恢复。')}</p>`,'<button type="button" id="cycleDone">继续阅读</button>');$('#cycleDone').onclick=closeCycleDialog;return}if(batch.status==='awaiting_page_decisions'){const patches=reviewCycleData?.page_patches?.[batch.batch_id]||[];const included=patches.filter(item=>item.decision==='include').length;const blocked=batch.one_click?.result_state==='blocked';cycleDialogShell(blocked?'已拦截修复候选':'逐页决定修复结果',blocked?'一键流未生成可验收候选；请查看每页原因后补充要求或关闭批次。':`已有 ${patches.length} 个 PagePatch；未查看、失败或“稍后”的页面不会进入最终候选。`,`<p class="cycle-note"><a target="_blank" href="/api/tasks/${reviewTask}/repair-batches/${batch.batch_id}/file/dual">预览本批次全部修复页</a></p>${patchBody(batch)}`,`<button class="ghost" type="button" id="cycleRejectBatch">关闭并保留当前版本</button><button type="button" id="cycleAssemble" ${included?'':'disabled'}>组装最终候选（${included} 页）</button>`);$('#cycleRejectBatch').onclick=()=>rejectBatch(batch.batch_id);$('#cycleAssemble').onclick=()=>assembleBatch(batch.batch_id);$('#cycleDialogBody').querySelectorAll('[data-patch-decision]').forEach(button=>button.onclick=()=>decidePatch(batch.batch_id,button));return}if(batch.status==='candidate_ready'){cycleDialogShell('最终候选等待验收',`仅列变更页；剔除任一页会自动重组候选。`,candidatePreviewBody(batch),`<button class="ghost" type="button" id="cycleRejectBatch">拒绝候选</button><button type="button" id="cycleAcceptBatch">接受并安装整本候选</button>`);$('#cycleRejectBatch').onclick=()=>rejectBatch(batch.batch_id);$('#cycleAcceptBatch').onclick=()=>acceptBatch(batch.batch_id);$('#cycleDialogBody').querySelectorAll('[data-patch-decision]').forEach(button=>button.onclick=()=>decidePatch(batch.batch_id,button));if(candidateObservationPending(batch)){startCandidateObservations(batch);scheduleCandidateObservationPoll(batch.batch_id)}return}cycleDialogShell('RepairBatch 状态',batch.status||'unknown',`<p class="cycle-note warning">${escapeHtml(batch.error||batch.progress?.message||'本批次需要关闭或重新建立。')}</p>`,'<button class="ghost" type="button" id="cycleRejectBatch">关闭批次</button>');$('#cycleRejectBatch').onclick=()=>rejectBatch(batch.batch_id)}
function showCycleError(message){const target=$('#cycleDialogError');target.textContent=message;target.hidden=false}
async function refreshCycleDialogError(message){await loadReview();openRepairBatchDialog();showCycleError(message)}
async function createBatch(){const keys=[...$('#cycleDialogBody').querySelectorAll('[data-repair-item]:checked')].map(item=>item.dataset.repairItem);if(!keys.length){showCycleError('请至少选择一项。');return}try{await api(`/api/tasks/${reviewTask}/repair-batches`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({repair_item_keys:keys})});closeCycleDialog();await loadReview();openRepairBatchDialog()}catch(error){await refreshCycleDialogError(error.message)}}
async function oneClickBatch(){const keys=[...$('#cycleDialogBody').querySelectorAll('[data-repair-item]:checked')].map(item=>item.dataset.repairItem);if(!keys.length){showCycleError('请至少选择一项。');return}const button=$('#cycleOneClickBatch');button.disabled=true;button.textContent='正在启动一键流…';try{await api(`/api/tasks/${reviewTask}/repair-batches/one-click`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({repair_item_keys:keys})});closeCycleDialog();await loadReview()}catch(error){button.disabled=false;button.textContent='生成可验收修复版';await refreshCycleDialogError(error.message)}}
async function startBatch(id){if(!confirm('确认按预检清单生成一次隔离候选？当前正式 PDF 不会改变。'))return;try{await api(`/api/tasks/${reviewTask}/repair-batches/${id}/start`,{method:'POST'});closeCycleDialog();await loadReview()}catch(error){await refreshCycleDialogError(error.message)}}
async function decidePatch(batchId,button){try{await api(`/api/tasks/${reviewTask}/repair-batches/${batchId}/page-patches/${button.dataset.patchId}/decision`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision:button.dataset.patchDecision,expected_version:Number(button.dataset.version||0)})});closeCycleDialog();await loadReview();openRepairBatchDialog()}catch(error){await refreshCycleDialogError(error.message)}}
async function assembleBatch(id){try{await api(`/api/tasks/${reviewTask}/repair-batches/${id}/candidate`,{method:'POST'});closeCycleDialog();await loadReview();openRepairBatchDialog()}catch(error){await refreshCycleDialogError(error.message)}}
async function acceptBatch(id){if(!confirm('确认已经预览变更页，并接受这份整本候选？系统会备份当前版本后原子替换。'))return;try{await api(`/api/tasks/${reviewTask}/repair-batches/${id}/accept`,{method:'POST'});closeCycleDialog();await loadReview();await tasks();await openTask(reviewTask,page,{keepReview:true})}catch(error){await refreshCycleDialogError(error.message)}}
async function rejectBatch(id){if(!confirm('关闭本批次并保留当前正式 PDF？已保存的 Comment 与审阅历史不会删除。'))return;try{await api(`/api/tasks/${reviewTask}/repair-batches/${id}/reject`,{method:'POST'});closeCycleDialog();await loadReview()}catch(error){await refreshCycleDialogError(error.message)}}
function bindReviewDetailActions(root){const preview=root.querySelector('[data-preview-page]');if(preview)preview.onclick=()=>{page=reviewPage.pdf_page;renderPage()};root.querySelectorAll('[data-decision]').forEach(button=>button.onclick=async()=>{await api(`/api/tasks/${reviewTask}/issues/${button.dataset.issue}/decision`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision:button.dataset.decision})});await loadReview()});root.querySelectorAll('[data-group-decision]').forEach(button=>button.onclick=async()=>{const issueIds=issueIdsFromDataset(button.dataset.groupIssues);for(const issueId of issueIds){await api(`/api/tasks/${reviewTask}/issues/${issueId}/decision`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision:button.dataset.groupDecision})})}await loadReview()});root.querySelectorAll('[data-comment-decision]').forEach(button=>button.onclick=async()=>{try{await decideComment(button.dataset.commentId,button.dataset.commentDecision,Number(button.dataset.version||0));await loadReview()}catch(error){alert(error.message);await loadReview()}});const feedback=$('#reviewFeedback');if(feedback&&!feedback.dataset.bound){feedback.dataset.bound='1';feedback.addEventListener('compositionstart',()=>reviewComposing=true);feedback.addEventListener('compositionend',()=>reviewComposing=false);feedback.addEventListener('blur',()=>reviewComposing=false)}root.querySelectorAll('[data-comment-seed]').forEach(button=>button.onclick=()=>{const seed=button.dataset.commentSeed||'';if(!feedback.value.trim())feedback.value=seed;else if(seed&&!feedback.value.includes(seed))feedback.value=`${feedback.value.trim()}\n${seed}`;issueIdsFromDataset(button.dataset.commentIssues||button.dataset.commentIssue).forEach(id=>{const checkbox=[...root.querySelectorAll('[data-issue-check]')].find(input=>issueIdsFromDataset(input.dataset.issueCheck).includes(id));if(checkbox&&!checkbox.disabled)checkbox.checked=true});feedback.focus()});const diagnose=$('#diagnoseSelected'),save=$('#saveComment'),send=$('#sendCommentNow');if(diagnose)diagnose.onclick=diagnoseSelected;if(save)save.onclick=()=>submitComment(false);if(send)send.onclick=()=>submitComment(true);const submitChecked=$('#submitCheckedComments'),submitPending=$('#submitPendingComments');if(submitChecked)submitChecked.onclick=()=>submitSelectedComments(false);if(submitPending)submitPending.onclick=()=>submitSelectedComments(true)}
function renderReviewDetail(){reviewComposing=false;const p=reviewPage;const actionable=p.issues.filter(isActionableIssue);const pending=actionable.filter(needsAction).length;const tips=technicalIssues(p);const human=pageHumanReviews(p);const comments=pageComments(p);const stale=reviewData?.qa?.freshness?.status==='stale';setTextIfChanged($('#reviewTitle'),`质量复核 · 第 ${p.pdf_page} 页`);setTextIfChanged($('#reviewSummary'),`${stale?'旧 QA 参考 · ':''}${pending?`${pending} 项${stale?'待确认':'需要处理'}`:'当前页无机器待办'}${comments.length?` · ${comments.length} 条 Comment`:''}`);const root=ensureReviewDetailSkeleton(`${reviewTask}:${p.pdf_page}`);root.classList.remove('review-empty');const scrollTop=root.scrollTop;const head=`<div class="detail-head"><span class="detail-kicker">${pending?'当前待办':'当前页'}</span><button class="ghost" data-preview-page="${p.pdf_page}">定位此页</button></div>`;const actionList=actionable.length?`${structuralOcrBanner(p,actionable)}<div class="issue-list">${renderIssueList(actionable)}</div>`:'<div class="action-clear">当前页无机器待办。你仍可在下方记录自己的发现。</div>';const humanList=human.length?`<section class="human-review-list"><h3>旧人工反馈与只读分析</h3>${human.map(humanReviewCard).join('')}</section>`:'';const commentsHtml=commentSection();const technical=tips.length?`<details class="technical-tips" data-detail-key="technical-tips"><summary><span>技术诊断 · ${tips.length} 条</span><small>默认无需处理，展开后可排查</small></summary>${structuralOcrBanner(p,tips)}<div class="issue-list">${renderIssueList(tips,{technical:true})}</div></details>`:'';const composer='<section class="comment-composer"><div class="comment-composer-head"><span aria-hidden="true">••</span><div><h3>你的补充意见（可选）</h3><p>记录你希望下一轮怎么处理；不会自动修改 PDF。</p></div></div><textarea id="reviewFeedback" aria-label="你的补充意见" placeholder="例如：只翻译上方表头；三张图保持不变。"></textarea><div class="diagnose-actions"><button id="saveComment">只保存 Comment</button><button class="ghost" id="sendCommentNow">立即发送审阅</button><button class="ghost" id="diagnoseSelected">分析选中机器问题</button></div><p class="comment-safety">保存只写入本地；发送审阅才会检查本机 Agent。机器问题仍走独立的只读诊断流程。</p></section>';patchReviewBlock(root,'head',head);patchReviewBlock(root,'issues',actionList);patchReviewBlock(root,'human',humanList);patchReviewBlock(root,'comments',commentsHtml);patchReviewBlock(root,'technical',technical);patchReviewBlock(root,'composer',composer);root.scrollTop=scrollTop;bindReviewDetailActions(root);restoreReviewDraft()}
async function diagnoseSelected(){const checked=[...$('#reviewDetail').querySelectorAll('[data-issue-check]:checked')].flatMap(item=>issueIdsFromDataset(item.dataset.issueCheck));const feedback=$('#reviewFeedback').value.trim();if(!checked.length){alert('请选择一个机器问题；普通人工发现请使用 Comment 保存或发送。');return}const button=$('#diagnoseSelected');button.disabled=true;button.textContent='正在提交只读分析…';try{await api(`/api/tasks/${reviewTask}/diagnose`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pdf_page:reviewPage.pdf_page,issue_ids:checked,feedback})});reviewDrafts.delete(reviewDraftKey());await loadReview()}catch(error){alert(error.message)}finally{button.disabled=false;button.textContent='分析选中机器问题'}}
async function submitComment(sendNow){const feedback=$('#reviewFeedback').value.trim();if(!feedback){alert('请先填写本页的人工发现。');return}const button=sendNow?$('#sendCommentNow'):$('#saveComment');button.disabled=true;try{await api(`/api/tasks/${reviewTask}/comments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pdf_page:reviewPage.pdf_page,feedback,submit:sendNow,provider:$('#provider')?.value||'claude'})});reviewDrafts.delete(reviewDraftKey());await loadReview()}catch(error){alert(error.message)}finally{button.disabled=false}}
async function submitSelectedComments(allPending){const ids=allPending?pageComments().filter(c=>['saved','review_failed'].includes(c.status)).map(c=>c.comment_id):[...$('#reviewDetail').querySelectorAll('[data-comment-check]:checked')].map(item=>item.dataset.commentCheck);if(!ids.length){alert('请选择待提交的 Comment。');return}await api(`/api/tasks/${reviewTask}/agent-reviews`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comment_ids:ids,provider:$('#provider')?.value||'claude'})});await loadReview()}
async function decideComment(id,decision,version){await api(`/api/tasks/${reviewTask}/comments/${id}/decision`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,note:'',expected_version:version})})}
function repairHistorySummary(record){if(!record)return'';if(record.status==='awaiting_acceptance')return'最新：已有候选等待人工查看和决定。';if(record.status==='advising')return'最新：Agent 正在生成只读建议。';if(record.status==='repairing')return'最新：正在生成候选并进行机器检查。';if(record.failure_stage==='executor_capability')return'最新：修复工具无法可靠识别该页面结构，已安全停止。';if(record.failure_stage==='june_visual_rejected')return'最新候选未通过人工视觉检查，当前 PDF 未改变。';if(record.failure_stage==='qa_machine_gate')return'最新候选未通过机器检查，当前 PDF 未改变。';if(record.status==='accepted')return'最新候选已由人工接受，旧版本已备份。';if(record.status==='stopped')return'最新处理已停止，当前 PDF 保持不变。';return'历史诊断、失败报告和候选决定均保留在这里。'}
function repairStatusLabel(status){return ({advising:'生成建议中',diagnosed:'已有只读建议',approved_for_batch:'已批准进入整篇批次',repairing:'生成候选中',awaiting_acceptance:'等待人工验收',repair_escalated:'安全停止 · 待决定',accepted:'已接受',batch_accepted:'已随整篇批次接受',rejected:'已拒绝',stopped:'已停止',escalation_decided:'记录已关闭',failed:'处理失败'})[status]||status}
function renderRepairHistory(){const target=$('#repairHistory');if(!reviewPage){setHtmlIfChanged(target,'','repair-history');return}const records=pageRepairRecords().sort((a,b)=>(b.updated_at||b.created_at||0)-(a.updated_at||a.created_at||0));if(!records.length){setHtmlIfChanged(target,'','repair-history');return}const latest=records[0];const openByDefault=['advising','repairing','awaiting_acceptance'].includes(latest.status);const html=`<details class="repair-history" data-detail-key="repair-history" ${openByDefault?'open':''}><summary><span class="history-icon" aria-hidden="true"></span><span class="history-copy"><b>历史处理记录 · ${records.length}</b><small>${escapeHtml(repairHistorySummary(latest))}</small><span class="history-toggle"><span class="history-expand">展开查看 ${records.length} 次记录</span><span class="history-collapse">收起记录</span></span></span></summary><div class="repair-history-list">${records.map(r=>repairCard(r)).join('')}</div></details>`;setHtmlIfChanged(target,html,`repair-history:${reviewTask}:${reviewPage.pdf_page}`);target.querySelectorAll('[data-repair-start]').forEach(b=>b.onclick=()=>repairAction(b.dataset.repairStart,'start'));target.querySelectorAll('[data-repair-batch]').forEach(b=>b.onclick=()=>approveRepairForBatch(b.dataset.repairBatch));target.querySelectorAll('[data-repair-accept]').forEach(b=>b.onclick=()=>repairAction(b.dataset.repairAccept,'accept'));target.querySelectorAll('[data-repair-reject]').forEach(b=>b.onclick=()=>repairAction(b.dataset.repairReject,'reject'));target.querySelectorAll('[data-repair-stop]').forEach(b=>b.onclick=()=>repairDecision(b.dataset.repairStop,'stop_keep_current'));target.querySelectorAll('[data-repair-alt]').forEach(b=>b.onclick=()=>repairDecision(b.dataset.repairAlt,b.dataset.strategy))}
function repairCard(r){const d=r.diagnosis;const advice=r.claude_advice||{};const alternatives=r.escalation_options?.alternatives||advice.alternatives||[];let body='';if(r.status==='advising'||r.status==='repairing')body=`<p class="working">${r.status==='advising'?'Claude 正在生成只读策略建议…':'正在按已保存策略生成一次候选并回归 QA…'}</p>`;else if(r.status==='failed')body=`<p class="error">${escapeHtml(r.error||'处理失败')}</p>`;else if(r.status==='approved_for_batch')body='<p class="working">已由你批准进入整篇修复池；可从“本篇审校进度”建立 RepairBatch。</p>';else if(r.status==='repair_escalated')body=`<p class="repair-stop-note"><b>本次处理已安全停止。</b><br>${escapeHtml(r.error||'候选未通过')}</p><div class="candidate"><a target="_blank" href="/api/tasks/${reviewTask}/repairs/${r.repair_id}/file/failure-md">下载 Markdown 报告</a><a target="_blank" href="/api/tasks/${reviewTask}/repairs/${r.repair_id}/file/failure-json">下载 JSON 报告</a><button class="ghost" data-repair-stop="${r.repair_id}">停止修复并保留当前版本</button>${alternatives.slice(0,3).map(a=>`<button class="ghost" data-repair-alt="${r.repair_id}" data-strategy="${escapeHtml(a.strategy_id)}">${escapeHtml(a.label||a.strategy_id)}</button>`).join('')}</div>`;else if(d)body=`<div class="diagnosis-grid"><p><b>${d.is_real_problem?'Claude 确认是真问题':'Claude 判断可能不需修复'}</b><br>${escapeHtml(d.explanation)}</p><dl><dt>问题族</dt><dd>${escapeHtml(d.root_cause)}</dd><dt>建议</dt><dd>${escapeHtml(d.recommended_action)}</dd><dt>范围</dt><dd>${escapeHtml(d.scope)}</dd><dt>风险 / 消耗</dt><dd>${escapeHtml(d.risk)} / ${escapeHtml(d.cost_level)}</dd></dl></div>`;const actions=r.status==='diagnosed'&&d?.is_real_problem?`<div class="candidate"><button data-repair-start="${r.repair_id}">立即生成单页候选</button><button class="ghost" data-repair-batch="${r.repair_id}">加入整篇修复批次</button></div>`:'';const candidate=r.status==='awaiting_acceptance'?`<div class="candidate"><a target="_blank" href="/api/tasks/${reviewTask}/repairs/${r.repair_id}/file/dual">预览候选双语 PDF</a><span>候选 QA：${escapeHtml(JSON.stringify(r.candidate?.qa_summary||{}))}</span><button data-repair-accept="${r.repair_id}">June 接受本次版本</button><button class="ghost" data-repair-reject="${r.repair_id}">拒绝并生成失败报告</button></div>`:'';const closed=['accepted','batch_accepted','rejected','stopped','escalation_decided'].includes(r.status)?`<p class="closed">${['accepted','batch_accepted'].includes(r.status)?'已由 June 接受，旧版本已备份':r.status==='stopped'?'June 已选择停止修复，当前 PDF 保留':'该记录已关闭，当前 PDF 未改变'}</p>`:'';return `<article class="repair-card"><header><span>第 ${r.pdf_page} 页</span><small>${escapeHtml(r.advisor_provider||r.provider||'claude')} · ${escapeHtml(repairStatusLabel(r.status))}</small></header>${body}${actions}${candidate}${closed}</article>`}
async function approveRepairForBatch(id){if(!confirm('把这条已诊断的机器问题加入整篇批准修复池？这里只记录批准，不会生成或覆盖 PDF。'))return;try{await api(`/api/tasks/${reviewTask}/repairs/${id}/batch-approve`,{method:'POST'});await loadReview()}catch(error){alert(error.message)}}
async function repairAction(id,action){if(action==='accept'&&!confirm('确认你已查看受影响页并接受本次候选版本？接受后会备份旧版本并替换当前下载文件。'))return;if(action==='reject'&&!confirm('拒绝会把本次候选记为视觉检查未通过并进入待拍板熔断态。继续吗？'))return;try{await api(`/api/tasks/${reviewTask}/repairs/${id}/${action}`,{method:'POST'});await loadReview();await tasks()}catch(error){alert(error.message)}}
function repairDecision(id,choice){const dialog=$('#repairDecisionDialog');pendingRepairDecision={id,choice};$('#repairDecisionTitle').textContent=choice==='stop_keep_current'?'停止修复并保留当前版本':'补充下一轮修复要求';$('#repairDecisionSummary').textContent=choice==='stop_keep_current'?'停止后不会创建新的 attempt，当前正式 PDF 保持不变。':'反馈只会进入新的 Claude 只读建议；不会自动生成候选。';$('#repairDecisionSubmit').textContent=choice==='stop_keep_current'?'确认停止修复':'创建只读建议 attempt';$('#repairDecisionNote').value='';$('#repairDecisionError').hidden=true;dialog.showModal();$('#repairDecisionNote').focus()}
async function submitRepairDecision(event){event.preventDefault();if(!pendingRepairDecision)return;const button=$('#repairDecisionSubmit');const errorBox=$('#repairDecisionError');button.disabled=true;errorBox.hidden=true;try{await api(`/api/tasks/${reviewTask}/repairs/${pendingRepairDecision.id}/decision`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({choice:pendingRepairDecision.choice,note:$('#repairDecisionNote').value})});$('#repairDecisionDialog').close();pendingRepairDecision=null;await loadReview()}catch(error){errorBox.textContent=error.message;errorBox.hidden=false}finally{button.disabled=false}}
function renderPage(){updatePager();if(!current||!currentTask)return;const url=`/api/tasks/${current}/file/${currentView}`;$('#openCurrent').href=`${url}#page=${page}`;$('#downloadCurrent').href=url;if(window.pdfWorkbenchViewer)window.pdfWorkbenchViewer.load(url,page)}
function syncReviewToPage(){if(reviewTask===current&&reviewData?.pages.some(p=>p.pdf_page===page))selectReviewPage(page,false)}
$('#prev').onclick=()=>goToPage(page-1);$('#next').onclick=()=>goToPage(page+1);$('#refresh').onclick=tasks;
$('#navLibrary').onclick=()=>{setLibraryOpen(true,{activate:true});$('#tasks').focus({preventScroll:true})};$('#brandLibrary').onclick=event=>{event.preventDefault();setLibraryOpen(true,{activate:true})};$('#navReader').onclick=()=>{if(!currentTask)return;setActiveWorkspace('reader');$('#pdfPageViewport').focus({preventScroll:true})};$('#navReview').onclick=()=>{if(!current||!currentTask?.qa_alpha_file)return;if(reviewTask===current&&reviewData)setReviewOpen(true,{activate:true});else showQa(current).catch(error=>alert(error.message))};document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>setReaderView(button.dataset.view));
function setControlOpen(open){const panel=$('#control');panel.classList.toggle('collapsed',!open);$('#toggleControl').innerHTML=open?'<span aria-hidden="true">−</span> 收起上传':'<span aria-hidden="true">＋</span> 上传 PDF'}
$('#toggleControl').onclick=()=>setControlOpen($('#control').classList.contains('collapsed'));
$('#libraryFold').onclick=()=>setLibraryOpen(!libraryOpen,{activate:false});
$('#paperFold').onclick=()=>setPaperHeaderOpen(!paperHeaderOpen);
$('#reviewFold').onclick=()=>{if($('#review').classList.contains('active'))setReviewOpen(false,{activate:false});else if(reviewTask===current&&reviewData)setReviewOpen(true,{activate:false});else if(current)showQa(current).catch(error=>alert(error.message))};
$('#closeReview').onclick=()=>closeReviewPanel({reset:true,activate:true});
$('#repairDecisionForm').onsubmit=submitRepairDecision;$('#repairDecisionCancel').onclick=()=>$('#repairDecisionDialog').close();$('#repairDecisionDialog').addEventListener('close',()=>{if($('#repairDecisionDialog').returnValue!=='')$('#repairDecisionDialog').returnValue='';pendingRepairDecision=null;$('#repairDecisionError').hidden=true});
$('#cycleDialogForm').onsubmit=event=>event.preventDefault();$('#cycleDialogClose').onclick=closeCycleDialog;$('#cycleDialog').addEventListener('close',()=>{$('#cycleDialogError').hidden=true;$('#cycleDialogBody').innerHTML='';$('#cycleDialogActions').innerHTML='' });
$('#shutdown').onclick=async()=>{try{const list=await api('/api/tasks');if(list.some(t=>t.status==='queued'||t.status==='running')){alert('仍有翻译任务运行，完成后才能退出程序。');return}if(!confirm('退出后网页将无法访问。确认关闭本地程序？'))return;const result=await api('/api/shutdown',{method:'POST'});document.body.innerHTML=`<main style="max-width:720px;margin:12vh auto"><h1 style="white-space:normal">程序已退出</h1><p>${escapeHtml(result.message)}</p><p>可以安全关闭这个页面。</p></main>`}catch(error){alert(error.message)}};
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function statusLabel(s){return ({completed:'已完成',completed_with_warnings:'有警告',needs_review:'需要复核',running:'运行中',queued:'排队中',uploaded:'待开始',waiting_ocr_install:'等待 OCR 安装',ocr_installing:'OCR 安装中',failed:'失败'})[s]||s}
window.addEventListener('pdf-viewer-ready',()=>renderPage());
window.addEventListener('pdf-document-loaded',event=>{pageCount=Math.max(1,Number(event.detail?.pages)||1);page=Math.min(pageCount,page);updatePager()});
window.addEventListener('pdf-page-change',event=>{pageCount=Math.max(1,Number(event.detail?.pages)||pageCount);page=Math.min(pageCount,Math.max(1,Number(event.detail?.page)||page));updatePager();syncReviewToPage()});
setLibraryOpen(libraryOpen,{activate:false});setPaperHeaderOpen(paperHeaderOpen);updateWorkspaceControls();updateViewerControls();updatePager();health().catch(e=>$('#health').textContent=e.message);tasks();setInterval(()=>{tasks();health().catch(()=>{});pollReview().catch(()=>{})},5000);
